<section class="panel expedicao-panel" data-tab-panel="recebimento" hidden>
  <div class="expedicao-heading"><div><h2>Confirmação de entrega</h2><p>Selecione uma entrega própria e registre a assinatura do destinatário.</p></div></div>
  <div class="expedicao-table-wrap"><table class="data-table expedicao-table entrega-table"><thead><tr><th>Pedido</th><th>Loja</th><th>Romaneio</th><th>Volumes</th><th>Expedido em</th><th>Status</th><th></th></tr></thead><tbody>
  <?php if(!empty($aguardandoRecebimento)):foreach($aguardandoRecebimento as $item):$pedidoEntrega=$item['pedido']??[];$lojaEntrega=trim((string)($pedidoEntrega['cliente_nome_fantasia']??''))?:trim((string)($pedidoEntrega['cliente_razao_social']??''));$dataEntrega=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false;?>
    <tr data-entrega-row="<?= (int)$item['id']; ?>"><td><strong><?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?></strong></td><td><span class="entrega-loja" title="<?= $esc($lojaEntrega); ?>"><?= $esc($lojaEntrega?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php if($dataEntrega):?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataEntrega); ?></strong><small><?= date('H:i:s',$dataEntrega); ?></small></span><?php else:?>—<?php endif;?></td><td><span class="entrega-status"><svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>Expedido</span></td><td><button type="button" class="button button-primary entrega-open" data-entrega-id="<?= (int)$item['id']; ?>" data-entrega-pedido="<?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?>">Entregar</button></td></tr>
  <?php endforeach;else:?><tr><td colspan="7" class="expedicao-empty">Nenhuma entrega própria aguardando confirmação.</td></tr><?php endif;?>
  </tbody></table></div>
</section>

<div class="entrega-modal" data-entrega-modal hidden><div class="entrega-modal__backdrop" data-entrega-close></div><section class="entrega-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="entrega-title"><header><div><h3 id="entrega-title">Confirmar entrega</h3><p>Pedido <strong data-entrega-pedido-label></strong></p></div><button type="button" class="entrega-modal__close" data-entrega-close aria-label="Fechar">×</button></header><form class="entrega-form" method="post" data-base-action="<?= $esc($url('expedicao/recebimento')); ?>"><input type="hidden" name="expedicao_id"><label><span>Nome do recebedor</span><input type="text" name="recebedor_nome" maxlength="120" required autocomplete="name" placeholder="Nome de quem recebeu"></label><label><span>Assinatura do recebedor</span><span class="entrega-signature-box"><canvas width="900" height="270" data-entrega-canvas></canvas><span class="entrega-signature-line"></span><button type="button" class="button button-outline entrega-clear" data-entrega-clear>Limpar</button></span><input type="hidden" name="assinatura_recebedor" data-entrega-value><small>Assine com o mouse ou toque sobre a linha.</small></label><div class="entrega-feedback" data-entrega-feedback></div><footer><button type="button" class="button button-outline" data-entrega-close>Cancelar</button><button type="submit" class="button button-primary" data-entrega-submit>Confirmar entrega</button></footer></form></section></div>

<style>
.entrega-table th,.entrega-table td{text-align:center!important;vertical-align:middle!important}.entrega-table thead th{font-size:10.6px!important}.entrega-table tbody td{font-size:13px!important;white-space:nowrap}.entrega-table th:nth-child(2),.entrega-table td:nth-child(2){width:170px;max-width:170px}.entrega-table tbody td:nth-child(2){height:46px!important;padding:6px!important;white-space:normal}.entrega-loja{display:-webkit-box;width:100%;height:32px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;line-height:16px;overflow-wrap:anywhere}.entrega-loja.is-long{font-size:12px!important}.entrega-loja.is-very-long{font-size:11px!important;line-height:15px}.entrega-status{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:#e0f2fe;color:#0369a1;font-size:12px;font-weight:850}.entrega-status svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.1}.entrega-modal{position:fixed;z-index:10020;inset:0;display:grid;place-items:center;padding:18px}.entrega-modal[hidden]{display:none}.entrega-modal__backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.entrega-modal__dialog{position:relative;width:min(650px,100%);padding:28px;border-radius:24px;background:#fff;box-shadow:0 28px 80px rgba(15,23,42,.3)}.entrega-modal__dialog header{display:flex;justify-content:space-between;gap:16px;margin-bottom:20px}.entrega-modal__dialog h3{margin:0 0 4px}.entrega-modal__dialog p{margin:0;color:var(--text-muted)}.entrega-modal__close{width:36px;height:36px;border:0;border-radius:11px;background:var(--surface-muted);font-size:24px;cursor:pointer}.entrega-form{display:grid;gap:17px}.entrega-form label{display:grid;gap:8px;font-weight:800}.entrega-form input[type=text]{width:100%;min-height:50px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit;box-sizing:border-box}.entrega-signature-box{position:relative;display:block;height:220px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,var(--border));border-radius:15px;background:#fff}.entrega-signature-box.has-signature{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 10%,transparent)}.entrega-signature-box canvas{position:absolute;z-index:2;inset:0;width:100%;height:100%;display:block;touch-action:none!important;pointer-events:auto!important;cursor:crosshair}.entrega-signature-line{position:absolute;z-index:1;left:9%;right:9%;bottom:28%;height:1px;background:#94a3b8;pointer-events:none}.entrega-clear{position:absolute;z-index:3;right:9px;top:9px;min-height:36px!important;padding:6px 11px!important}.entrega-form small{color:var(--text-muted)}.entrega-feedback{min-height:18px;font-size:13px;font-weight:750}.entrega-feedback.error{color:#b91c1c}.entrega-feedback.success{color:#15803d}.entrega-form footer{display:flex;justify-content:flex-end;gap:10px}.entrega-form footer .button{min-height:46px;justify-content:center}@media(max-width:600px){.entrega-modal{padding:10px}.entrega-modal__dialog{padding:20px}.entrega-signature-box{height:190px}.entrega-form footer{display:grid;grid-template-columns:1fr 1fr}}
</style>

<script>
(()=>{const modal=document.querySelector('[data-entrega-modal]'),form=modal?.querySelector('.entrega-form'),canvas=form?.querySelector('[data-entrega-canvas]'),hidden=form?.querySelector('[data-entrega-value]'),box=form?.querySelector('.entrega-signature-box'),clearButton=form?.querySelector('[data-entrega-clear]'),submit=form?.querySelector('[data-entrega-submit]'),feedback=form?.querySelector('[data-entrega-feedback]');if(!modal||!form||!canvas||!hidden||!box||!clearButton||!submit)return;const ctx=canvas.getContext('2d');let drawing=false,hasInk=false,last=null,lastPointer=0;ctx.strokeStyle='#111827';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';const coordinates=(clientX,clientY)=>{const rect=canvas.getBoundingClientRect();return{x:(clientX-rect.left)*canvas.width/rect.width,y:(clientY-rect.top)*canvas.height/rect.height}};const persist=()=>{if(!hasInk)return false;hidden.value=canvas.toDataURL('image/png');box.classList.add('has-signature');feedback.textContent='Assinatura capturada.';feedback.className='entrega-feedback success';return true};const begin=(clientX,clientY,event)=>{event?.preventDefault?.();drawing=true;hasInk=true;last=coordinates(clientX,clientY);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(last.x+.4,last.y+.4);ctx.stroke();feedback.textContent='Assinando...';feedback.className='entrega-feedback';if(event?.pointerId!=null)try{canvas.setPointerCapture(event.pointerId)}catch(error){}};const draw=(clientX,clientY,event)=>{if(!drawing)return;event?.preventDefault?.();const current=coordinates(clientX,clientY);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(current.x,current.y);ctx.stroke();last=current};const finish=()=>{if(!drawing)return;drawing=false;last=null;persist()};canvas.addEventListener('pointerdown',event=>{lastPointer=Date.now();begin(event.clientX,event.clientY,event)});canvas.addEventListener('pointermove',event=>draw(event.clientX,event.clientY,event));window.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('mousedown',event=>{if(Date.now()-lastPointer<700)return;begin(event.clientX,event.clientY,event)});window.addEventListener('mousemove',event=>{if(Date.now()-lastPointer<700)return;draw(event.clientX,event.clientY,event)});window.addEventListener('mouseup',()=>{if(Date.now()-lastPointer>=700)finish()});canvas.addEventListener('touchstart',event=>{const touch=event.touches[0];if(touch)begin(touch.clientX,touch.clientY,event)},{passive:false});canvas.addEventListener('touchmove',event=>{const touch=event.touches[0];if(touch)draw(touch.clientX,touch.clientY,event)},{passive:false});canvas.addEventListener('touchend',finish,{passive:false});const reset=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hidden.value='';drawing=false;hasInk=false;last=null;box.classList.remove('has-signature');feedback.textContent='';feedback.className='entrega-feedback'};clearButton.addEventListener('click',reset);const close=()=>{modal.hidden=true;document.body.style.overflow='';form.reset();reset()};document.querySelectorAll('[data-entrega-close]').forEach(button=>button.addEventListener('click',close));document.querySelectorAll('[data-entrega-id]').forEach(button=>button.addEventListener('click',()=>{reset();form.action=`${form.dataset.baseAction}/${encodeURIComponent(button.dataset.entregaId)}`;form.elements.expedicao_id.value=button.dataset.entregaId;modal.querySelector('[data-entrega-pedido-label]').textContent=button.dataset.entregaPedido||'';modal.hidden=false;document.body.style.overflow='hidden';form.elements.recebedor_nome.focus()}));form.addEventListener('submit',async event=>{event.preventDefault();if(!persist()){feedback.textContent='Faça a assinatura do recebedor.';feedback.className='entrega-feedback error';return}if(form.dataset.saving==='1')return;form.dataset.saving='1';submit.disabled=true;submit.textContent='Salvando...';try{const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível salvar a entrega.');feedback.textContent='Assinatura salva com sucesso.';feedback.className='entrega-feedback success';setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){feedback.textContent=error.message||'Não foi possível salvar a entrega.';feedback.className='entrega-feedback error'}finally{delete form.dataset.saving;submit.disabled=false;submit.textContent='Confirmar entrega'}},true);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close()});document.querySelectorAll('.entrega-loja').forEach(loja=>{const length=loja.textContent.trim().length;loja.classList.toggle('is-long',length>34&&length<=55);loja.classList.toggle('is-very-long',length>55)})})();
</script>
